def normalize_query(query):
    query = query.strip()
    if not query:
        raise ValueError("Query cannot be empty")
    return query.lower()

# Test the function
print(normalize_query("  Hello World  "))  # Output: "hello world"
print(normalize_query(""))  # Output: Error: Query cannot be empty

This function takes a user query as input, normalizes it by removing leading and trailing whitespace, and converting the query to lowercase. It then checks if the query is empty after trimming and raises a ValueError if it is. This ensures that the query is valid and non-empty before proceeding with any further processing.

def create_rag_context(records):
    context = {
        "Assets": {
            "Total": 0,
            "Current": 0,
            "Non-Current": 0
        },
        "Liabilities": {
            "Total": 0,
            "Current": 0,
            "Non-Current": 0
        },
        "Equity": {
            "Total": 0
        }
    }

    for record in records:
        if record["Source"] == "Balance Sheet":
            context["Assets"]["Total"] += record["Amount"]
            if record["Class"] == "Current":
                context["Assets"]["Current"] += record["Amount"]
            else:
                context["Assets"]["Non-Current"] += record["Amount"]
        elif record["Source"] == "Income Statement":
            if record["Class"] == "Revenue":
                context["Revenue"] = record["Amount"]
        elif record["Source"] == "Cash Flow":
            if record["Class"] == "Operating Activities":
                context["Operating Activities"] = record["Amount"]
        elif record["Source"] == "Financial Ratios":
            if record["Class"] == "Return on Assets":
                context["Return on Assets"] = record["Amount"]
            elif record["Class"] == "Return on Equity":
                context["Return on Equity"] = record["Amount"]

    context["Liabilities"]["Total"] = context["Assets"]["Total"] - context["Equity"]["Total"]
    context["Liabilities"]["Current"] = context["Assets"]["Current"] - context["Equity"]["Total"]
    context["Liabilities"]["Non-Current"] = context["Assets"]["Non-Current"] - context["Equity"]["Total"]

    return context

# Example usage
records = [
    {
        "Source": "Balance Sheet",
        "Class": "Current",
        "Amount": 1000
    },
    {
        "Source": "Balance Sheet",
        "Class": "Non-Current",
        "Amount": 2000
    },
    {
        "Source": "Income Statement",
        "Class": "Revenue",
        "Amount": 3000
    },
    {
        "Source": "Cash Flow",
        "Class": "Operating Activities",
        "Amount": 4000
    },
    {
        "Source": "Financial Ratios",
        "Class": "Return on Assets",
        "Amount": 0.10
    },
    {
        "Source": "Financial Ratios",
        "Class": "Return on Equity",
        "Amount": 0.20
    }
]

rag_context = create_rag_context(records)
print(rag_context)

